  fun ms' => exists (t0' t1' t2' a6' a7' t3' t4' t5' t6' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 (Z_to_bv 64 (INST + 728)) (Z_to_bv 64 (T + 80)) (Z_to_bv 64 (T + 208))
