             F (Z_to_bv 64 qput_entry') fc None m' (seg_rom asegs)
    /\ munch [(M + 16, M + 24); (d_tab, d_nuniq + 4); (d_map1, d_map1 + 8); (DNB, DNB + 2 ^ 20); (s_total, s_total + 8);
             (s_data0, s_stored0 + 4); (SSB, SSB + 2 ^ 23); (bv_unsigned sp - 272, bv_unsigned sp)]%Z m m'
