    /\ stk asegs m' lo (bv_unsigned sp).

Lemma qchunk_spec : forall ra sp gp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (M n b1 B TCX T lo : Z) (ctx w : word) (D : depot) (BK : list Z) (DNB SSB : Z)
    (ws rest : list word),
  (kHighShadowEnd < M)%Z -> (M + 24 <= lo)%Z -> (1 <= n < 2^32)%Z -> (0 <= b1 < 256)%Z ->
  rw_cells asegs m M [C1 (Z_to_bv 8 3); C1 (Z_to_bv 8 b1); C2 (Z_to_bv 64 0); C4 (Z_to_bv 64 n); C8 ctx] ->
  rw_cells asegs m (M + 16) [C8 w] ->
  thread_cells TCX T m -> (0 < TCX)%Z -> (TCX + 0xa0 <= lo)%Z -> (0 < T)%Z -> (T + 4096 <= 0x10000 \/ 0x785000 <= T)%Z ->
  (T + 4096 <= lo)%Z ->
  rw_cells asegs m T [C8 (Z_to_bv 64 TCX)] -> rw_cells asegs m (TCX + 8) [C4 (Z_to_bv 64 0)] ->
  rw_cells asegs m B [C8 (Z_to_bv 64 (B + 16)); C8 (Z_to_bv 64 (Z.of_nat (length ws)))] ->
  u64arr asegs m (B + 16) (ws ++ rest) -> length (ws ++ rest) = 255%nat -> (1 <= Z.of_nat (length ws) <= 254)%Z ->
  depot_ok D DNB SSB lo -> depot_rep D BK DNB SSB m -> (d_tot D + Z.of_nat (length ws) + 1 < 2^20)%Z ->
  In (bkt (depot_hash (map bv_unsigned ws))) BK -> (d_n D + 2 < 2^16)%Z ->
  (M + 24 <= DNB \/ DNB + 2 ^ 20 <= M)%Z -> (M + 24 <= SSB \/ SSB + 2 ^ 23 <= M)%Z ->
  stk asegs m lo (bv_unsigned sp) -> (lo <= bv_unsigned sp - 272)%Z -> (bv_unsigned sp <= B)%Z -> (B + 2064 <= 2^47)%Z ->
  mem_inv asegs m ->
  evt asegs (qchunk_post ra sp gp (Z_to_bv 64 tpA) s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc M n B T D BK DNB SSB ws rest lo m)
    (MS (mkR ra sp gp (Z_to_bv 64 tpA) t0 t1 t2 s0 s1 (Z_to_bv 64 INST) (Z_to_bv 64 M) (Z_to_bv 64 (M + 16)) (Z_to_bv 64 B)
             a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 qchunk_entry') fc None m (seg_rom asegs)).
Proof.
